```c
int get_idna_map (uint32_t c, IDNAMap * map)
{
    uint8_t *p;

    if (c <= 0xFF)
        p = (uint8_t *)bsearch (&c, idna_map_8, sizeof (idna_map_8) / 5, 5,
                   (int (*)(const void *, const void *)) _compare_idna_map);
    else if (c <= 0xFFFF)
        p = (uint8_t *)bsearch (&c, idna_map_16, sizeof (idna_map_16) / 7, 7,
                   (int (*)(const void *, const void *)) _compare_idna_map);
    else if (c <= 0xFFFFFF)
        p = (uint8_t *)bsearch (&c, idna_map_24, sizeof (idna_map_24) / 8, 8,
                   (int (*)(const void *, const void *)) _compare_idna_map);
    else
        p = NULL;

    if (!p)
    {
        memset (map, 0, sizeof (IDNAMap));
        return -1;
    }

    _fill_map (c, p, map);
    return 0;
}
```

This function doesn't modify any global state. It just looks up the code point in the appropriate map and fills in the `IDNAMap` structure. So the behavior is deterministic.

